/**
 * Background Service Worker
 * 处理插件的后台逻辑
 */

// 监听插件安装事件
chrome.runtime.onInstalled.addListener((details) => {
  console.log('[Furigana] Extension installed:', details.reason);

  if (details.reason === 'install') {
    // 首次安装，设置默认选项
    chrome.storage.local.set({
      globalEnabled: true,
      autoProcess: false  // 默认不自动处理，需要用户手动启用
    });
  }
});

// 监听来自 content script 或 popup 的消息
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  console.log('[Furigana Background] Received message:', message, 'from:', sender);

  switch (message.type) {
    case 'GET_TAB_ID':
      // 返回当前 tab ID
      if (sender.tab?.id) {
        sendResponse({ tabId: sender.tab.id });
      } else {
        sendResponse({ error: 'No tab ID available' });
      }
      break;

    case 'INJECT_SCRIPT':
      // 向指定 tab 注入内容脚本（如果需要动态注入）
      if (message.tabId) {
        chrome.scripting.executeScript({
          target: { tabId: message.tabId },
          files: ['content_script.js']
        }).then(() => {
          sendResponse({ success: true });
        }).catch((error) => {
          sendResponse({ success: false, error: error.message });
        });
        return true; // 异步响应
      }
      break;

    default:
      sendResponse({ error: 'Unknown message type' });
  }

  return false;
});

// 监听 tab 更新事件（可选：用于自动检测日文页面）
chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (changeInfo.status === 'complete' && tab.url) {
    // 可以在这里添加逻辑来自动检测日文新闻网站
    // 例如：检测特定域名列表
    const japaneseNewsSites = [
      'nhk.or.jp',
      'asahi.com',
      'yomiuri.co.jp',
      'mainichi.jp',
      'nikkei.com',
      'sankei.com',
      'tokyo-np.co.jp',
      'chunichi.co.jp',
      'news.yahoo.co.jp'
    ];

    const isJapaneseNewsSite = japaneseNewsSites.some(site =>
      tab.url?.includes(site)
    );

    if (isJapaneseNewsSite) {
      // 更新图标状态等
      console.log('[Furigana Background] Japanese news site detected:', tab.url);
    }
  }
});

// 监听快捷键命令（可选）
chrome.commands?.onCommand.addListener((command) => {
  console.log('[Furigana Background] Command received:', command);

  if (command === 'toggle-furigana') {
    // 获取当前活动 tab 并切换状态
    chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
      if (tabs[0]?.id) {
        chrome.tabs.sendMessage(tabs[0].id, { type: 'TOGGLE_ENABLED' });
      }
    });
  }
});

console.log('[Furigana Background] Service worker started');
